// 🎯 Intelligent Request Analyzer & Router
// Analyzes incoming requests and routes to appropriate agents

const input = $json.body.message || $json.body.query || '';
const userId = $json.body.userId || 'default';
const sessionId = $json.body.sessionId || Date.now().toString();

// Analyze request complexity
function analyzeComplexity(text) {
  const factors = {
    length: text.length,
    hasCode: /```|function|class|const|let|var/.test(text),
    hasResearch: /research|analyze|study|investigate|compare/.test(text),
    hasCreative: /write|create|generate|compose|draft/.test(text),
    hasMultiStep: /and|then|also|after|before/.test(text),
    hasTechnical: /api|code|debug|optimize|algorithm/.test(text)
  };

  let score = 0;
  if (factors.length > 500) score += 3;
  if (factors.hasCode) score += 4;
  if (factors.hasResearch) score += 3;
  if (factors.hasCreative) score += 2;
  if (factors.hasMultiStep) score += 3;
  if (factors.hasTechnical) score += 4;

  return {
    score,
    level: score < 5 ? 'simple' : score < 10 ? 'medium' : score < 15 ? 'complex' : 'expert',
    factors
  };
}

// Determine agent type
function determineAgent(text, complexity) {
  const lower = text.toLowerCase();

  // Research Agent
  if (/research|analyze|study|investigate|compare|data|statistics/.test(lower)) {
    return 'research';
  }

  // Content Creator Agent
  if (/write|create|generate|compose|draft|article|blog|content/.test(lower)) {
    return 'content';
  }

  // Code Assistant Agent
  if (/code|debug|optimize|function|api|algorithm|programming/.test(lower)) {
    return 'code';
  }

  // Email Agent
  if (/email|send|reply|gmail|message/.test(lower)) {
    return 'email';
  }

  // Calendar Agent
  if (/calendar|meeting|schedule|event|appointment/.test(lower)) {
    return 'calendar';
  }

  // YouTube Agent
  if (/youtube|video|watch|channel/.test(lower)) {
    return 'youtube';
  }

  // Web Agent
  if (/search|weather|news|web|internet|google/.test(lower)) {
    return 'web';
  }

  // Meta Agent
  if (/create.*agent|add.*integration|modify.*system/.test(lower)) {
    return 'meta';
  }

  // Default to research for complex, content for simple
  return complexity.score > 10 ? 'research' : 'content';
}

const complexity = analyzeComplexity(input);
const agentType = determineAgent(input, complexity);

return {
  json: {
    input,
    userId,
    sessionId,
    complexity,
    agentType,
    timestamp: new Date().toISOString(),
    metadata: {
      requestLength: input.length,
      estimatedTokens: Math.ceil(input.length / 4),
      priority: complexity.level === 'expert' ? 'high' : 'normal'
    }
  }
};

// 🔬 Research Agent Pro - Advanced research with intelligent model selection

const input = $input.item.json.input;
const complexity = $input.item.json.complexity;
const sessionId = $input.item.json.sessionId;

// Load intelligent router
const IntelligentRouter = require('/scripts/ai-core/intelligent-router-pro');
const router = new IntelligentRouter();

// Research-specific system prompt
const systemPrompt = `You are Research Agent Pro, an advanced AI researcher.

Capabilities:
- Deep analysis of complex topics
- Multi-source information synthesis
- Statistical analysis and data interpretation
- Comparative studies
- Trend analysis
- Academic-quality research

Always:
- Provide well-researched, accurate information
- Cite sources when possible
- Structure findings clearly
- Highlight key insights
- Suggest related areas for exploration`;

// Execute research with intelligent model selection
async function executeResearch() {
  try {
    const response = await router.executeWithCache(
      input,
      {
        systemPrompt,
        complexity: complexity.level,
        type: 'research',
        maxTokens: 2000,
        temperature: 0.7,
        sessionId
      }
    );

    return {
      json: {
        agent: 'research',
        response: response.content,
        model: response.model,
        cached: response.cached || false,
        cost: response.cost || 0,
        tokens: response.tokens || { input: 0, output: 0 },
        timestamp: new Date().toISOString(),
        success: true
      }
    };
  } catch (error) {
    return {
      json: {
        agent: 'research',
        error: error.message,
        success: false
      }
    };
  }
}

return await executeResearch();

