// 📊 Response Aggregator & Analytics

const result = $input.item.json;
const originalRequest = $('🧠 Request Analyzer').item.json;

// Load budget guardian for cost tracking
const BudgetGuardian = require('/scripts/monitoring/budget-guardian');
const guardian = new BudgetGuardian();

// Track cost
if (result.cost && result.cost > 0) {
  guardian.trackCost(result.cost, result.model || 'unknown');
}

// Get budget status
const budgetStatus = guardian.getStatus();

// Format response
const formattedResponse = {
  // Core response
  success: result.success || false,
  agent: result.agent,
  response: result.response || result.error,

  // Request metadata
  request: {
    input: originalRequest.input,
    complexity: originalRequest.complexity.level,
    estimatedTokens: originalRequest.metadata.estimatedTokens
  },

  // Execution metadata
  execution: {
    model: result.model,
    cached: result.cached || false,
    cost: result.cost || 0,
    tokens: result.tokens || { input: 0, output: 0 },
    timestamp: result.timestamp
  },

  // Budget info
  budget: {
    used: budgetStatus.used,
    limit: budgetStatus.limit,
    percentage: budgetStatus.percentage,
    remaining: budgetStatus.remaining,
    status: budgetStatus.status
  },

  // Performance metrics
  performance: {
    responseTime: Date.now() - new Date(originalRequest.timestamp).getTime(),
    cacheHit: result.cached || false,
    costSavings: result.cached ? result.cost : 0
  }
};

return { json: formattedResponse };
